public ConfigGroup itemStealing = new ConfigGroup("itemStealing", true);
@ConfigGroup.Pop
@Translatable.Name(value="Thievery Pounce Chance")
@Translatable.Desc(value="Probability (0.1 to 1.0) a hamster will succumb to temptation when seeing a stealable item. High by default, since the only default stealable item is a diamond.")
public ValidatedFloat itemThieveryChance = new ValidatedFloat(0.75f, 1.0f, 0.1f);
@Translatable.Name(value="Tag Game")
@Translatable.Desc(value="Hamsters get bored. Sometimes they want to play. Configure the rules of engagement here.")
public ConfigGroup tagGame = new ConfigGroup("tagGame", true);
@Translatable.Name(value="Allow Stranger Danger")
@Translatable.Desc(value="If true, hamsters can ask any player to play. If false, they can only ask their owners.")
public boolean allowStrangerTag = true;
@Translatable.Name(value="Game Initiation Chance")
@Translatable.Desc(value="The 1-in-X chance per tick a hamster will start a game of tag with you if you make too much eye contact. Since the game runs at 20 ticks per second, a 1-in-500-tick chance means you'll need to maintain eye contact for about ~15 seconds on average. Set to 1 if you want the game to start instantly upon eye contact.")
public ValidatedInt tagChanceDenominator = new ValidatedInt(500, 1200, 1);
@Translatable.Name(value="Enable Player Daily Limit")
@Translatable.Desc(value="If true, players are capped on how many games they can play per day. If false, you can play until your legs fall off.")
public ValidatedBoolean enableTagGamePlayerLimit = new ValidatedBoolean(true);
private final ValidatedField<Boolean> isTagLimitEnabled = this.enableTagGamePlayerLimit.map(b -> b, b -> b);
@Translatable.Name(value="Max Games Per Day")
@Translatable.Desc(value="How many times a single player can be 'It' per Minecraft day before telling the rodents to go find a hobby. Prevents infinite reward farming.")
public ValidatedCondition<Integer> maxDailyTagGamesPerPlayer = new ValidatedInt(3, 100, 0).toCondition(this.isTagLimitEnabled, (Component)Component.m_237115_((String)"config.adorablehamsterpets.condition.tag_limit_enabled"), () -> 3);
@ConfigGroup.Pop
@Translatable.Name(value="Inter-Hamster Tag Duration")
@Translatable.Desc(value="How long (in seconds) the chase lasts before the hamsters get bored and the game ends. This only applies if the Chaser fails to catch the Instigator.")
public ValidatedInt interHamsterTagMaxDurationSeconds = new ValidatedInt(10, 60, 3);
@Translatable.Name(value="Hide & Seek")
@Translatable.Desc(value="Settings for when your hamster decides it's time to disappear into the woodwork.")
public ConfigGroup hideAndSeek = new ConfigGroup("hideAndSeek", true);
@Translatable.Name(value="Initiation Chance")
@Translatable.Desc(value="1-in-X chance per tick to initiate a game of hide and seek. Default 7200 (20 ticks per second, so default averages once every ~6 minutes).")
public ValidatedInt hideAndSeekChanceDenominator = new ValidatedInt(7200, 72000, 20);
@Translatable.Name(value="Min Duration")
@Translatable.Desc(value="Minimum time (in seconds) the hamster will stay hidden.")
public ValidatedInt hideAndSeekMinDurationSeconds = new ValidatedInt(45, 600, 1);
@Translatable.Name(value="Max Duration")
@Translatable.Desc(value="Maximum time (in seconds) before the hamster gets board, gives up and sulks.")
public ValidatedInt hideAndSeekMaxDurationSeconds = new ValidatedInt(60, 600, 5);
@Translatable.Name(value="Allow Storage Blocks")
@Translatable.Desc(value="If true, hamsters can hide inside chests, barrels, and other valid blocks that have inventories. This checks whether the block implements an inventory interface, so it will work regardless of the content in the 'Valid Hiding Blocks' list.")
public boolean allowInventoryHiding = true;
@Translatable.Name(value="Valid Hiding Blocks")
@Translatable.Desc(value="A list of blocks or tags where the hamster is allowed to hide.")
public List<String> validHidingBlocks = new ArrayList<String>(List.of("#adorablehamsterpets:bushes"));
@ConfigGroup.Pop.Container(value={@ConfigGroup.Pop, @ConfigGroup.Pop, @ConfigGroup.Pop})
@Translatable.Name(value="Hiding Blacklist")
@Translatable.Desc(value="Blocks with inventories that the hamster should never hide inside. This overrides everything else.")
public List<String> inventoryHidingBlacklist = new ArrayList<String>(List.of("minecraft:furnace", "minecraft:blast_furnace", "minecraft:smoker", "minecraft:dispenser", "minecraft:dropper", "minecraft:hopper", "minecraft:campfire", "minecraft:soul_campfire"));
@Translatable.Name(value="Commissioned Features")
@Translatable.Desc(value="Specialized, unofficial mechanics funded by supporters that don't necessarily fit the theme of the mod. Purposefully tucked away in the config to ensure most people don't notice them.")
public ConfigGroup commissionedFeatures = new ConfigGroup("commissionedFeatures", true);
@Translatable.Name(value="Surface Redstone Fever")
@Translatable.Desc(value="Optional surface Redstone Fever settings. The settings here are subordinate to the global Redstone Fever feature toggle.")
public ConfigGroup ultimateNightmareRedstoneFever = new ConfigGroup("ultimateNightmareRedstoneFever", true);
@Translatable.Name(value="Enable Surface Fever")
@Translatable.Desc(value="Allow healthy wild hamsters to randomly and instantly become infected with Redstone Fever when first approached by a Survival or Adventure player. The dice gets rolled once per hamster even if they are approached again later. So a hamster that doesn't turn on you after you approach can be trusted.")
public ValidatedBoolean enableSurfaceSurpriseRedstoneFever = new ValidatedBoolean(false);
private final ValidatedField<Boolean> isSurfaceSurpriseEnabled = this.enableSurfaceSurpriseRedstoneFever.map(value -> value, value -> value);
@Translatable.Name(value="Infection Chance")
@Translatable.Desc(value="Percentage chance that an undecided hamster contracts Redstone Fever on first approach.")
public ValidatedCondition<Integer> surfaceSurpriseFeverChance = new ValidatedInt(25, 100, 0).toCondition(this.isSurfaceSurpriseEnabled, (Component)Component.m_237115_((String)"config.adorablehamsterpets.condition.surface_surprise_enabled"), () -> 25);
@ConfigGroup.Pop
@Translatable.Name(value="Trigger Distance")
@Translatable.Desc(value="Distance in blocks at which the first eligible player causes the dice roll.")
public ValidatedCondition<Integer> surfaceSurpriseRevealDistance = new ValidatedInt(8, 40, 1).toCondition(this.isSurfaceSurpriseEnabled, (Component)Component.m_237115_((String)"config.adorablehamsterpets.condition.surface_surprise_enabled"), () -> 8);
@Translatable.Name(value="Hamster Riding Settings")
@Translatable.Desc(value="Configure hamster-mounted cavalry. Tweak speeds, toggles, and physics. Don't blame me if you accidentally zoom off a cliff after turning up the speed too high.")
public ConfigGroup hamsterRiding = new ConfigGroup("hamsterRiding", true);
@Translatable.Name(value="Enable Hamster Riding")
@Translatable.Desc(value="Adds a keybind to mount hamsters. (It's unbound by default). Allows riding any hamster, but you can only steer your own. \n\nCommissioned by @Saint_Victus.")
public ValidatedBoolean enableMountableHamsters = new ValidatedBoolean(false);
private final ValidatedField<Boolean> isRidingEnabled = this.enableMountableHamsters.map(b -> b, b -> b);
@Translatable.Name(value="Base Ride Speed")
@Translatable.Desc(value="The casual strolling speed multiplier. 0.25 is the default. Don't ask why.")
public ValidatedCondition<Double> ridingBaseSpeedMultiplier = new ValidatedDouble(0.25, 0.8, 0.0).toCondition(this.isRidingEnabled, (Component)Component.m_237115_((String)"config.adorablehamsterpets.condition.riding_enabled"), () -> 0.25);
@ConfigGroup.Pop
@Translatable.Name(value="Sprint Ride Speed")
@Translatable.Desc(value="The speed multiplier when sprinting. Hold on to your acorn hat. 0.35 is the default. I wish it was a nice round number, but alas, hamster riding is a complex enigma.")
public ValidatedCondition<Double> ridingSprintSpeedMultiplier = new ValidatedDouble(0.35, 1.0, 0.0).toCondition(this.isRidingEnabled, (Component)Component.m_237115_((String)"config.adorablehamsterpets.condition.riding_enabled"), () -> 0.8);
@Translatable.Name(value="Feather Yeeting Settings")
@Translatable.Desc(value="Configure the commissioned Feather Yeeting status effect.")
public ConfigGroup featherYeeting = new ConfigGroup("featherYeeting", true);
@ConfigGroup.Pop.Container(value={@ConfigGroup.Pop, @ConfigGroup.Pop})
@Translatable.Name(value="Throw Cooldown Reduction")
@Translatable.Desc(value="Percentage removed from a hamster's base throw cooldown when the throwing player has Feather Yeeting. 0% preserves the base cooldown; 100% removes it.")
public ValidatedInt featherYeetingCooldownReductionPercent = new ValidatedInt(50, 100, 0);

public AhpMainConfig() {
    super(ResourceLocation.m_214293_((String)"adorablehamsterpets", (String)"main"));
}

@NotNull
public SaveType saveType() {
    return SaveType.SEPARATE;
}

