@Translation(prefix="adorablehamsterpets.main.armorPbrValues")
public static class ArmorPbrValues {
    @NonSync
    @Translatable.Name(value="Emissiveness")
    @Translatable.Desc(value="The Alpha channel. How much it glows in the dark. 0 is dark, 254 is a tiny blinding sun. DO NOT set it to 255. LabPBR ignores 255 entirely, so it actually means zero glow.")
    public ValidatedInt emissive;
    @NonSync
    @Translatable.Name(value="Porosity & SSS")
    @Translatable.Desc(value="The Blue channel. 0-64 controls Porosity (how much darker it gets when wet). 65-255 controls Subsurface Scattering (light passing through, like skin/wax). 65 is completely solid, 255 is pure translucent rodent gelatin.")
    public ValidatedInt sss;
    @NonSync
    @Translatable.Name(value="Reflectance & Metallic")
    @Translatable.Desc(value="The Green channel. 0-229 controls standard reflectance. 230-254 triggers hardcoded metals in your shader (230=Iron, 231=Gold, etc). 255 tells the shader to tint the reflection based on the texture's color.")
    public ValidatedInt metallic;
    @NonSync
    @Translatable.Name(value="Smoothness")
    @Translatable.Desc(value="The Red channel. 0 is rough sandpaper. 255 is a perfectly polished mirror.")
    public ValidatedInt smoothness;

    public ArmorPbrValues(int emissive, int sss, int metallic, int smoothness) {
        this.emissive = new ValidatedInt(emissive, 255, 0);
        this.sss = new ValidatedInt(sss, 255, 0);
        this.metallic = new ValidatedInt(metallic, 255, 0);
        this.smoothness = new ValidatedInt(smoothness, 255, 0);
    }

    public ArmorPbrValues() {
        this(0, 0, 0, 0);
    }
}

