@Translatable.Name(value="Supporter Perks")
@Translatable.Desc(value="For the generous souls who keep the hamster wheels spinning. Here are your exclusive settings for tweaking cosmetics.")
public class AhpSupporterConfig
extends Config {
    @Translatable.Name(value="The Pixie Dust Crown")
    @Translatable.Desc(value="Settings for the majestic, spinning ring of pixie dust hovering above your head.")
    public ConfigGroup supporterParticleCrown = new ConfigGroup("supporterParticleCrown", false);
    @NonSync
    @Translatable.Name(value="Enable Crowns")
    @Translatable.Desc(value="Master switch. Turn this off if you hate fun. Disables all crowns, even those worn by others.")
    public boolean enableSupporterCrown = true;
    @NonSync
    @Translatable.Name(value="Enable Crown Audio")
    @Translatable.Desc(value="Turns off the sparkling sound effects the emanate from the crown. Affects all crowns, even those worn by others.")
    public boolean enableCrownAudio = true;
    @NonSync
    @Translatable.Name(value="Crown Audio Volume")
    @Translatable.Desc(value="How loud the crown sparkles are. Crank it up if your 50 sound physics mods made it inaudible, or turn it down if the majestic twinkling is eroding your sanity.")
    public ValidatedFloat crownAudioVolume = new ValidatedFloat(1.0f, 2.0f, 0.1f);
    @NonSync
    @Translatable.Name(value="Show My Crown")
    @Translatable.Desc(value="Toggle this off if you want to hide your own crown from yourself and everyone else. Only affects your own crown.")
    public boolean showMyCrown = true;
    @NonSync
    @Translatable.Name(value="Show in First Person")
    @Translatable.Desc(value="Should your own crown decorate your vision while you're trying to mine? Turn it off if you are tired of flexing on yourself. Only affects your own crown.")
    public boolean showCrownInFirstPerson = true;
    @NonSync
    @Translatable.Name(value="Color Theme")
    @Translatable.Desc(value="Pick your own crown's specific color. Other players will instantly see this color change above your head. Only affects your own crown.")
    public ValidatedEnum<PixieDustParticleTheme> crownTheme = new ValidatedEnum((Enum)PixieDustParticleTheme.GOLD);
    @NonSync
    @Translatable.Name(value="Particle Count")
    @Translatable.Desc(value="How many sparkly particles to spawn per tick (20 ticks per second). Makes the crown thicker or thinner. Affects all crowns.")
    public ValidatedInt crownParticleCount = new ValidatedInt(10, 30, 1);
    @NonSync
    @Translatable.Name(value="Radius")
    @Translatable.Desc(value="How wide (in blocks) the halo of superiority extends around your head. Affects all crowns.")
    public ValidatedDouble crownRadius = new ValidatedDouble(0.3, 1.0, 0.1);
    @NonSync
    @Translatable.Name(value="Thickness")
    @Translatable.Desc(value="How thick the crown is from the inner edge (the inside rim around your head) to the outer edge. Affects all crowns.")
    public ValidatedDouble crownHorizontalThickness = new ValidatedDouble(0.02, 1.0, 0.0);
    @NonSync
    @Translatable.Name(value="Height")
    @Translatable.Desc(value="How tall the crown is from the bottom edge to the top edge. Increase this to make the crown less of a hula-hoop and more of a cylinder. Affects all crowns.")
    public ValidatedDouble crownVerticalThickness = new ValidatedDouble(0.2, 1.0, 0.0);
    @NonSync
    @ConfigGroup.Pop.Container(value={@ConfigGroup.Pop, @ConfigGroup.Pop})
    @Translatable.Name(value="Vertical Offset")
    @Translatable.Desc(value="Nudge the crown up or down. Move it high enough and you'll have a halo. Vanity for the win. Affects all crowns.")
    public ValidatedDouble crownYOffset = new ValidatedDouble(0.25, 2.0, -2.0);

    public AhpSupporterConfig() {
        super(ResourceLocation.m_214293_((String)"adorablehamsterpets", (String)"supporter_perks"));
    }

    @NotNull
    public SaveType saveType() {
        return SaveType.SEPARATE;
    }
}

