import net.minecraft.ChatFormatting;
import net.minecraft.client.Minecraft;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import org.jetbrains.annotations.NotNull;

@Translatable.Name(value="Visuals & UI")
@Translatable.Desc(value="Client-side aesthetics, performance toggles, and HUD elements.")
public class AhpUiConfig
extends Config {
    @Translatable.Name(value="UI & Quality of Life")
    @Translatable.Desc(value="Here's where you can tweak the knobs and dials for anything that pops up on your screen.")
    public ConfigGroup uiPreferences = new ConfigGroup("uiPreferences", true);
    @Translatable.Name(value="Guidebook Settings")
    @Translatable.Desc(value="Settings related to the 'Hamster Tips' guide book and how aggressively I nag you about it.")
    public ConfigGroup guidebookSettings = new ConfigGroup("guidebookSettings", true);
    @Translatable.Name(value="Auto Delivery")
    @Translatable.Desc(value="Hand-delivers the sacred texts on first login.")
    public boolean enableAutoGuidebookDelivery = true;
    @Translatable.Name(value="Auto Delivery Fallback")
    @Translatable.Desc(value="If Auto Delivery is disabled (like in most modpacks), give the guidebook the first time the player actually spots a wild hamster from 10 blocks away. This will only trigger once, and only if the player has never received the guidebook before.")
    public boolean enableAutoGuidebookDeliveryFallback = true;
    @NonSync
    @Translatable.Name(value="Seen Warning Players")
    @Translatable.Desc(value="A list of players who have already seen the missing guidebook warning. This helps ensure that each player sees the warning only once. It was broken for a while, but it is fixed as of v3.7.0.")
    public List<String> playersWhoHaveSeenGuidebookWarning = new ArrayList<String>();
    @NonSync
    @ConfigGroup.Pop
    @Translatable.Name(value="Warning Timer")
    @Translatable.Desc(value="How long (in ticks) I wait before realizing you're book-less and panicking. 3600 = 3 minutes.")
    public ValidatedInt guidebookWarningTimer = new ValidatedInt(3600, 6000, 100);
    @Translatable.Name(value="Jade Overlay Settings")
    @Translatable.Desc(value="Fine-tune the voyeuristic amount of genetic data you see when staring at a hamster. Also includes toggles for Jade's default info. Note that these toggles do not affect any entities except hamsters.")
    public ConfigGroup jadeOverlaySettings = new ConfigGroup("jadeOverlaySettings", true);
    @NonSync
    @Translatable.Name(value="Require Sneak for Custom Info")
    @Translatable.Desc(value="If true, you must hold sneak to expose their genetic secrets. If false, their DNA is proudly broadcasted to you at all times. Set to False by default so I don't get spammed on Discord.")
    public boolean requireSneakForCustomJadeInfo = false;
    @NonSync
    @Translatable.Name(value="Require Sneak for Default Info")
    @Translatable.Desc(value="If true, the default Jade info will also be hidden unless you are actively sneaking. This setting only matters if 'Require Sneaking' is enabled above.")
    public boolean requireSneakForDefaultJadeInfo = false;
    @NonSync
    @Translatable.Name(value="Show Entity Name")
    @Translatable.Desc(value="Display the default Jade entity name. You know, 'Hampter'.")
    public boolean showJadeEntityName = true;
    @NonSync
    @Translatable.Name(value="Show Health")
    @Translatable.Desc(value="Display the default Jade health hearts. In case you want to know exactly how close your hamster is to the great beyond.")
    public boolean showJadeEntityHealth = true;
    @NonSync
    @Translatable.Name(value="Show Growth Time")
    @Translatable.Desc(value="Display the default Jade growth timer that shows how long until babies become adults. Useful if you believe age is just a feeling.")
    public boolean showJadeGrowthTime = true;
    @NonSync
    @Translatable.Name(value="Show Owner")
    @Translatable.Desc(value="Display the default Jade owner name. So everyone knows who is responsible when it happens.")
    public boolean showJadeOwner = true;
    @NonSync
    @Translatable.Name(value="Show Age")
    @Translatable.Desc(value="Display how long this hamster has managed to survive your world.")
