@Translatable.Name(value="World Gen & Loot")
@Translatable.Desc(value="Control the rodent population density, where their food grows, and what they scavenge for. Changes here usually require a restart, or at least a deep breath. Note: If you join a server, its world gen settings will override yours.")
public class AhpWorldGenConfig
extends Config {
    @Translatable.Name(value="Hamster Spawn Settings")
    @Translatable.Desc(value="How Many, Where, and How Often?  Note: Some of these settings require re-logging into your world to take effect.")
    public ConfigGroup hamsterSpawning = new ConfigGroup("hamsterSpawning", true);
    @Translatable.Name(value="Spawn Weight")
