    @Translatable.Name(value="Allow Spawns In")
    @Translatable.Desc(value="Step One: Do hamsters exist here at all? If a biome matches these tags or IDs, the universe permits their presence. Once allowed to spawn, they fall through the 'Region-Based Color Filters' filters below to figure out what color they should be.")
    public ConfigGroup allowTheseSpawnsGlobally = new ConfigGroup("allowTheseSpawnsGlobally", true);
