private static Map<HamsterColorZone, Integer> parseWeights(List<String> weightStrings, String envName) {
    EnumMap<HamsterColorZone, Integer> weights = new EnumMap<HamsterColorZone, Integer>(HamsterColorZone.class);
    for (String str : weightStrings) {
        String[] parts = str.split(":");
        if (parts.length != 2) continue;
        try {
            HamsterColorZone zone = HamsterColorZone.valueOf(parts[0].trim().toUpperCase(Locale.ROOT));
            int weight = Integer.parseInt(parts[1].trim());
            if (weight <= 0) continue;
            weights.put(zone, weight);
        }
        catch (IllegalArgumentException e) {
            AdorableHamsterPets.LOGGER.warn("[ConfigDataCache] Invalid weight zone '{}' in {}", (Object)str, (Object)envName);
        }
    }
    if (weights.isEmpty()) {
        weights.put(HamsterColorZone.ORANGE, 100);
    }
    return weights;
}

